        self.value = value
        self.next = next

def build(values):
    dummy = Node(0)
    cur = dummy
    for v in values:
        cur.next = Node(v)
        cur = cur.next
    return dummy.next

def remove_nth_from_end(head, n):
    dummy = Node(0, head)
    fast = slow = dummy
    for _ in range(n + 1):
        fast = fast.next
    while fast:
        fast = fast.next
        slow = slow.next
    slow.next = slow.next.next
    return dummy.next

def to_list(head):
    out = []
    while head:
        out.append(head.value)
        head = head.next
    return out

