class DNode:
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

    def append(self, value):
        node = DNode(value)
        if self.tail is None:
            self.head = self.tail = node
        else:
            node.prev = self.tail
            self.tail.next = node
            self.tail = node

    def forward(self):
        vals, cur = [], self.head
        while cur:
            vals.append(str(cur.value))
            cur = cur.next
        return " <-> ".join(vals)

dll = DoublyLinkedList()
for v in (1, 2, 3):
    dll.append(v)
